var MarketingBase=function(n){var t={initialize:function(){n("#btnGenerateLink").on("click",function(){MarketingBase.generateTextLink()});new ClipboardJS(".btn-copy-link");new ClipboardJS(".btn-copy-qr",{text:function(t){let i=n(t).nextAll("img")[0];return i.outerHTML}});n(".btn-save-img").click(function(){let i=n(this).nextAll("img").attr("src"),t=document.createElement("a");t.href=i;t.download="qr-code.png";t.click()})},generateTextLink:function(){var n=t.getLinkGenerationParam();t.getTextLink(n)},getLinkGenerationParam:function(){return{selectedLanguage:n("#Language").val(),selectedDomainId:n("#Domain").val(),selectedPage:n("#MemberSitePage").val()}},getTextLink:function(t){n.ajax({type:"GET",dataType:"html",cache:!1,data:t,url:Site.resolveRelativeUrl("UserPanel/Marketing/GenerateLink"),success:function(t){n("#textLinkList").html(t)},beforeSend:function(){Site.showLoader()},complete:function(){Site.hideLoader()}})}};return t}(jQuery);$(document).ready(function(){MarketingBase.initialize()});